    const bolster = new THREE.BoxGeometry(2.14, 0.24, 0.92);
    const sideFrame = new THREE.BoxGeometry(0.12, 0.18, 3.22);
    const airBag = new THREE.CylinderGeometry(0.29, 0.31, 0.22, 14);
    const coilSpring = new THREE.CylinderGeometry(0.085, 0.085, 0.24, 10);
